import csv, json, datetime, collections

fees = json.load(open('inputs/fees.json'))
merchants = {m['merchant']: m for m in json.load(open('inputs/merchant_data.json'))}

def capture_ok(rule, actual):
    if rule is None:
        return True
    if rule in ('immediate', 'manual'):
        return actual == rule
    d = int(actual)
    if rule == '<3':
        return d < 3
    if rule == '3-5':
        return 3 <= d <= 5
    if rule == '>5':
        return d > 5
    raise ValueError(rule)

def fraud_level_ok(rule, rate):
    if rule is None:
        return True
    pct = rate * 100
    if rule.startswith('<'):
        return pct < float(rule[1:-1])
    if rule.startswith('>'):
        return pct > float(rule[1:-1])
    lo, hi = rule[:-1].split('-')
    return float(lo.rstrip('%')) <= pct <= float(hi.rstrip('%'))

def volume_ok(rule, volume):
    if rule is None:
        return True
    def number(text):
        text = text.lower()
        return float(text[:-1]) * (1000 if text.endswith('k') else 1000000)
    if rule.startswith('<'):
        return volume < number(rule[1:])
    if rule.startswith('>'):
        return volume > number(rule[1:])
    lo, hi = rule.split('-')
    return number(lo) <= volume <= number(hi)

def matches(rule, tx, monthly):
    m = merchants[tx['merchant']]
    return (
        rule['card_scheme'] == tx['card_scheme']
        and (not rule['account_type'] or m['account_type'] in rule['account_type'])
        and capture_ok(rule['capture_delay'], m['capture_delay'])
        and fraud_level_ok(rule['monthly_fraud_level'], monthly['fraud_rate'])
        and volume_ok(rule['monthly_volume'], monthly['volume'])
        and (not rule['merchant_category_code'] or m['merchant_category_code'] in rule['merchant_category_code'])
        and (rule['is_credit'] is None or rule['is_credit'] == (tx['is_credit'] == 'True'))
        and (not rule['aci'] or tx['aci'] in rule['aci'])
        and (rule['intracountry'] is None or bool(rule['intracountry']) == (tx['issuing_country'] == tx['acquirer_country']))
    )

def fee(rule, value):
    return rule['fixed_amount'] + rule['rate'] * value / 10000.0

# Static fee-rule answers
mcc_by_description = {}
with open('inputs/merchant_category_codes.csv', newline='') as f:
    for row in csv.DictReader(f):
        mcc_by_description[row['description']] = int(row['mcc'])

gc_credit = [f for f in fees if f['card_scheme'] == 'GlobalCard' and f['is_credit'] in (True, None)]
ans_1273 = sum(fee(f, 10.0) for f in gc_credit) / len(gc_credit)

mcc_5812 = mcc_by_description['Eating Places and Restaurants']
gc_h_5812 = [
    f for f in fees
    if f['card_scheme'] == 'GlobalCard'
    and (not f['account_type'] or 'H' in f['account_type'])
    and (not f['merchant_category_code'] or mcc_5812 in f['merchant_category_code'])
]
ans_1305 = sum(fee(f, 10.0) for f in gc_h_5812) / len(gc_h_5812)

ids_1464 = sorted(
    f['ID'] for f in fees
    if (not f['account_type'] or 'R' in f['account_type'])
    and (not f['aci'] or 'B' in f['aci'])
)

issuing_counts = collections.Counter()
fraud_ip_counts = collections.Counter()
martinis_volume = 0.0
martinis_fraud_volume = 0.0
belles_rows = collections.defaultdict(list)
belles_monthly = collections.defaultdict(lambda: {'volume': 0.0, 'fraud_volume': 0.0})

with open('inputs/payments.csv', newline='') as f:
    for tx in csv.DictReader(f):
        issuing_counts[tx['issuing_country']] += 1
        if tx['has_fraudulent_dispute'] == 'True':
            fraud_ip_counts[tx['ip_country']] += 1

        amount = float(tx['eur_amount'])
        if tx['merchant'] == 'Martinis_Fine_Steakhouse':
            martinis_volume += amount
            if tx['has_fraudulent_dispute'] == 'True':
                martinis_fraud_volume += amount

        if tx['merchant'] == 'Belles_cookbook_store':
            dt = datetime.datetime(2023, 1, 1) + datetime.timedelta(days=int(tx['day_of_year']) - 1)
            month = dt.month
            belles_rows[month].append(tx)
            belles_monthly[month]['volume'] += amount
            if tx['has_fraudulent_dispute'] == 'True':
                belles_monthly[month]['fraud_volume'] += amount

for month, monthly in belles_monthly.items():
    monthly['fraud_rate'] = monthly['fraud_volume'] / monthly['volume']

ans_5 = issuing_counts.most_common(1)[0][0]
top_fraud_ip = fraud_ip_counts.most_common(1)[0][0]
option = {'NL': 'A', 'BE': 'B', 'ES': 'C', 'FR': 'D'}[top_fraud_ip]
ans_49 = f'{option}. {top_fraud_ip}'
ans_70 = 'yes' if (martinis_fraud_volume / martinis_volume) * 100 > 8.3 else 'no'

def applicable_ids(txs, monthly):
    result = set()
    for tx in txs:
        result.update(f['ID'] for f in fees if matches(f, tx, monthly))
    return sorted(result)

day10 = [
    tx for tx in belles_rows[1]
    if (datetime.datetime(2023, 1, 1) + datetime.timedelta(days=int(tx['day_of_year']) - 1)).day == 10
]
ans_1681 = ', '.join(map(str, applicable_ids(day10, belles_monthly[1])))
ans_1753 = ', '.join(map(str, applicable_ids(belles_rows[3], belles_monthly[3])))

rule_384 = next(f for f in fees if f['ID'] == 384)
id384_amount = sum(float(tx['eur_amount']) for tx in belles_rows[1] if matches(rule_384, tx, belles_monthly[1]))
ans_1871 = f'{(1 - rule_384["rate"]) * id384_amount / 10000.0:.14f}'

fraud_rows = [tx for tx in belles_rows[1] if tx['has_fraudulent_dispute'] == 'True']
aci_costs = {}
for aci in 'ABCDEFG':
    total = 0.0
    for original in fraud_rows:
        tx = original.copy()
        tx['aci'] = aci
        candidates = [fee(f, float(tx['eur_amount'])) for f in fees if matches(f, tx, belles_monthly[1])]
        total += min(candidates) if candidates else 0.0
    aci_costs[aci] = total
best_aci = min(aci_costs, key=aci_costs.get)
ans_2697 = f'{best_aci}:{aci_costs[best_aci]:.2f}'

answers = [
    {'task_id': '5', 'answer': ans_5},
    {'task_id': '49', 'answer': ans_49},
    {'task_id': '70', 'answer': ans_70},
    {'task_id': '1273', 'answer': f'{ans_1273:.6f}'},
    {'task_id': '1305', 'answer': f'{ans_1305:.6f}'},
    {'task_id': '1464', 'answer': ', '.join(map(str, ids_1464))},
    {'task_id': '1681', 'answer': ans_1681},
    {'task_id': '1753', 'answer': ans_1753},
    {'task_id': '1871', 'answer': ans_1871},
    {'task_id': '2697', 'answer': ans_2697},
]
with open('answers.jsonl', 'w', encoding='utf-8') as f:
    for item in answers:
        f.write(json.dumps(item, ensure_ascii=False, separators=(',', ':')) + '\n')
print('counts:', len(gc_credit), len(gc_h_5812), len(ids_1464))
print('averages:', ans_1273, ans_1305)
print('fraud rates:', (martinis_fraud_volume / martinis_volume) * 100, belles_monthly[1]['fraud_rate'] * 100, belles_monthly[3]['fraud_rate'] * 100)
print('day10 ids:', ans_1681)
print('march ids:', ans_1753)
print('id384 amount/delta:', id384_amount, ans_1871)
print('ACI costs:', {k: round(v, 6) for k, v in aci_costs.items()}, 'best', ans_2697)
