def capture_ok(rule, actual):
    if rule is None:
        return True
    if rule in ('immediate', 'manual'):
        return actual == rule
    d = int(actual)
    if rule == '<3':
        return d < 3
    if rule == '3-5':
        return 3 <= d <= 5
    if rule == '>5':
        return d > 5
    raise ValueError(rule)

def fraud_level_ok(rule, rate):
    if rule is None:
        return True
    pct = rate * 100
    if rule.startswith('<'):
        return pct < float(rule[1:-1])
    if rule.startswith('>'):
        return pct > float(rule[1:-1])
    lo, hi = rule[:-1].split('-')
    return float(lo.rstrip('%')) <= pct <= float(hi.rstrip('%'))

def volume_ok(rule, volume):
    if rule is None:
        return True
    def number(text):
        text = text.lower()
        return float(text[:-1]) * (1000 if text.endswith('k') else 1000000)
    if rule.startswith('<'):
        return volume < number(rule[1:])
    if rule.startswith('>'):
        return volume > number(rule[1:])
    lo, hi = rule.split('-')
    return number(lo) <= volume <= number(hi)

